export function productFor(id: string): ProductIntel | null {
  const base = productIntel[id];
  const extra = PRODUCT_TECH[id];
  if (!base && !extra) return null;
  if (!extra) return base ?? null;
  const tech = [...(base?.tech || []), ...(extra.tech || [])].filter((x, i, a) => a.indexOf(x) === i);
  if (!base) {
    return {
      seriesId: "",
      captured: PRODUCT_CAPTURED,
      source: "公开口径",
      hv: extra.hv,
      batteryTech: extra.batteryTech,
      adas: extra.adas,
      tech: extra.tech,
    };
  }
  return {
    ...base,
    hv: extra.hv || base.hv,
    batteryTech: extra.batteryTech || base.batteryTech,
    adas: extra.adas || base.adas,
    tech: tech.length ? tech : base.tech,
  };
}
